export interface Post {
  id: number
  title: string
  content: string
}

const posts: Post[] = []
let nextId = 1

export async function getPosts(): Promise<Post[]> {
  return posts
}

export async function insertPost(data: {
  title: string
  content: string
}): Promise<Post> {
  const post = { id: nextId++, ...data }
  posts.push(post)
  return post
}

